    categories:["Sixteenth Army","Red Army field armies","Western Front","Battle of Smolensk","Operation Barbarossa"],facts:[["Formed","July 1940 <sup class='canon-note' data-provenance='p'>[p]</sup>"],["Formation district","Transbaikal Military District <sup class='canon-note' data-provenance='p'>[p]</sup>"],["Commander on 31 July","Mikhail Lukin <sup class='canon-note' data-provenance='p'>[p]</sup>"],["Westward movement","May–June 1941 <sup class='canon-note' data-provenance='p'>[p]</sup>"],["Redirected","Orsha–Smolensk axis · 26 June 1941 <sup class='canon-note' data-provenance='p'>[p]</sup>"],["Principal battle","Battle of Smolensk <sup class='canon-note' data-provenance='p'>[p]</sup>"],["Historical 8 August transition","Not inherited automatically <sup class='canon-note' data-provenance='e'>[e]</sup>"],["Status from 1 August","Open in detail <sup class='canon-note' data-provenance='e'>[e]</sup>"]]
